	snapshotFixture := strings.Replace(semanticFixtureSnapshot("1.0"), "\n{\"record_type\":\"symbol\"", "\n{\"record_type\":\"file\",\"path\":\"internal/auth/token.go\",\"language\":\"Go\"}\n{\"record_type\":\"symbol\"", 1)
