			t.Fatalf("load semantic source: manifest=%+v err=%v", manifest, err)
		}
		return manifest.Sources.Semantic
	}
	readSymbols := func(source *semanticSourceManifest) []string {
		t.Helper()
		brainDir, err := brainDirForKey(env, "gh/example/repo")
		if err != nil {
			t.Fatal(err)
		}
